CREATE OR REFRESH MATERIALIZED VIEW `cg_demo_a54027b9e561_defective_gold_issues`
AS WITH ps AS (SELECT * FROM `cg_demo_a54027b9e561_defective_silver_profiles` WHERE side='source'), pc AS (SELECT * FROM `cg_demo_a54027b9e561_defective_silver_profiles` WHERE side='candidate'), ts AS (SELECT * FROM `cg_demo_a54027b9e561_defective_silver_in_window` WHERE side='source' AND CAST(event_time AS TIMESTAMP)>=CAST(window_start AS TIMESTAMP) AND CAST(event_time AS TIMESTAMP)<CAST(window_end AS TIMESTAMP)), tc AS (SELECT * FROM `cg_demo_a54027b9e561_defective_silver_in_window` WHERE side='candidate' AND CAST(event_time AS TIMESTAMP)>=CAST(window_start AS TIMESTAMP) AND CAST(event_time AS TIMESTAMP)<CAST(window_end AS TIMESTAMP)) SELECT 'identity' check_id, 'profile_missing' type, coalesce(s.account_id,c.account_id) key, 'account_id' field, s.account_id source_value, c.account_id candidate_value FROM ps s FULL OUTER JOIN pc c ON s.account_id=c.account_id WHERE c.account_id IS NULL UNION ALL SELECT 'identity' check_id, 'profile_extra' type, coalesce(s.account_id,c.account_id) key, 'account_id' field, s.account_id source_value, c.account_id candidate_value FROM ps s FULL OUTER JOIN pc c ON s.account_id=c.account_id WHERE s.account_id IS NULL UNION ALL SELECT 'identity' check_id, 'customer_mismatch' type, coalesce(s.account_id,c.account_id) key, 'customer_id' field, s.customer_id source_value, c.customer_id candidate_value FROM ps s FULL OUTER JOIN pc c ON s.account_id=c.account_id WHERE s.account_id IS NOT NULL AND c.account_id IS NOT NULL AND s.customer_id <> c.customer_id UNION ALL SELECT 'transactions' check_id, 'event_missing' type, coalesce(s.event_id,c.event_id) key, 'event_id' field, CAST(s.event_id AS STRING) source_value, CAST(c.event_id AS STRING) candidate_value FROM ts s FULL OUTER JOIN tc c ON s.event_id=c.event_id WHERE c.event_id IS NULL UNION ALL SELECT 'transactions' check_id, 'event_extra' type, coalesce(s.event_id,c.event_id) key, 'event_id' field, CAST(s.event_id AS STRING) source_value, CAST(c.event_id AS STRING) candidate_value FROM ts s FULL OUTER JOIN tc c ON s.event_id=c.event_id WHERE s.event_id IS NULL UNION ALL SELECT 'transactions' check_id, 'account_mismatch' type, coalesce(s.event_id,c.event_id) key, 'account_id' field, CAST(s.account_id AS STRING) source_value, CAST(c.account_id AS STRING) candidate_value FROM ts s FULL OUTER JOIN tc c ON s.event_id=c.event_id WHERE s.event_id IS NOT NULL AND c.event_id IS NOT NULL AND s.account_id <> c.account_id UNION ALL SELECT 'transactions' check_id, 'amount_mismatch' type, coalesce(s.event_id,c.event_id) key, 'amount_minor' field, CAST(s.amount_minor AS STRING) source_value, CAST(c.amount_minor AS STRING) candidate_value FROM ts s FULL OUTER JOIN tc c ON s.event_id=c.event_id WHERE s.event_id IS NOT NULL AND c.event_id IS NOT NULL AND s.amount_minor <> c.amount_minor UNION ALL SELECT 'transactions' check_id, 'currency_mismatch' type, coalesce(s.event_id,c.event_id) key, 'currency' field, CAST(s.currency AS STRING) source_value, CAST(c.currency AS STRING) candidate_value FROM ts s FULL OUTER JOIN tc c ON s.event_id=c.event_id WHERE s.event_id IS NOT NULL AND c.event_id IS NOT NULL AND s.currency <> c.currency UNION ALL SELECT 'transactions' check_id, 'timestamp_mismatch' type, coalesce(s.event_id,c.event_id) key, 'event_time' field, CAST(s.event_time AS STRING) source_value, CAST(c.event_time AS STRING) candidate_value FROM ts s FULL OUTER JOIN tc c ON s.event_id=c.event_id WHERE s.event_id IS NOT NULL AND c.event_id IS NOT NULL AND s.event_time <> c.event_time;

CREATE OR REFRESH MATERIALIZED VIEW `cg_demo_a54027b9e561_defective_gold_impacts`
AS WITH balances AS (
SELECT side, account_id, currency, sum(amount_minor) amount FROM `cg_demo_a54027b9e561_defective_silver_in_window`
WHERE CAST(event_time AS TIMESTAMP)>=CAST(window_start AS TIMESTAMP) AND CAST(event_time AS TIMESTAMP)<CAST(window_end AS TIMESTAMP)
GROUP BY side,account_id,currency), s AS (SELECT * FROM balances WHERE side='source'), c AS (SELECT * FROM balances WHERE side='candidate')
SELECT coalesce(s.account_id,c.account_id) account_id,coalesce(s.currency,c.currency) currency,
coalesce(s.amount,CAST(0 AS DECIMAL(38,0))) source_minor,coalesce(c.amount,CAST(0 AS DECIMAL(38,0))) candidate_minor,
coalesce(c.amount,CAST(0 AS DECIMAL(38,0)))-coalesce(s.amount,CAST(0 AS DECIMAL(38,0))) delta_minor
FROM s FULL OUTER JOIN c ON s.account_id=c.account_id AND s.currency=c.currency;

CREATE OR REFRESH MATERIALIZED VIEW `cg_demo_a54027b9e561_defective_gold_totals`
AS WITH changed AS (
SELECT DISTINCT key FROM `cg_demo_a54027b9e561_defective_gold_issues` WHERE check_id='transactions'), inwindow AS (
SELECT * FROM `cg_demo_a54027b9e561_defective_silver_in_window` WHERE CAST(event_time AS TIMESTAMP)>=CAST(window_start AS TIMESTAMP) AND CAST(event_time AS TIMESTAMP)<CAST(window_end AS TIMESTAMP)), affected AS (
SELECT s.currency,abs(s.amount_minor) amount FROM inwindow s JOIN changed k ON s.event_id=k.key WHERE s.side='source'
UNION ALL SELECT c.currency,abs(c.amount_minor) amount FROM inwindow c JOIN changed k ON c.event_id=k.key
LEFT JOIN inwindow s ON s.side='source' AND s.event_id=c.event_id WHERE c.side='candidate' AND (s.event_id IS NULL OR s.currency<>c.currency)), notional AS (
SELECT currency,sum(amount) affected_notional_minor FROM affected GROUP BY currency)
SELECT a.currency,sum(a.source_minor) source_minor,sum(a.candidate_minor) candidate_minor,
sum(a.delta_minor) net_delta_minor,sum(abs(a.delta_minor)) absolute_account_delta_minor,
coalesce(n.affected_notional_minor,CAST(0 AS DECIMAL(38,0))) affected_notional_minor
FROM `cg_demo_a54027b9e561_defective_gold_impacts` a LEFT JOIN notional n ON a.currency=n.currency GROUP BY a.currency,n.affected_notional_minor;

